// formatBranchHeader returns the header for branch-level explain output.
func formatBranchHeader(branchName string, checkpointCount int, isDefault bool, limit int) string {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Branch: %s\n", branchName))
	if isDefault && limit > 0 {
		sb.WriteString(fmt.Sprintf("(showing last %d checkpoints)\n", limit))
	}
	sb.WriteString(fmt.Sprintf("Checkpoints: %d\n", checkpointCount))
	return sb.String()
}

// formatBranchExplain

func TestFormatBranchHeader(t *testing.T) {
	tests := []struct {
		name            string
		branchName      string
		checkpointCount int
		isDefault       bool
		limit           int
		wantContains    []string
		wantNotContains []string
	}{
		{
			name:            "feature branch no limit",
			branchName:      "feature/my-feature",
			checkpointCount: 5,
			isDefault:       false,
			limit:           0,
			wantContains:    []string{"Branch: feature/my-feature", "Checkpoints: 5"},
			wantNotContains: []string{"showing last"},
		},
		{
			name:            "main branch with default limit",
			branchName:      "main",
			checkpointCount: 15,
			isDefault:       true,
			limit:           10,
			wantContains:    []string{"Branch: main", "showing last 10 checkpoints", "Checkpoints: 15"},
			wantNotContains: []string{},
		},
		{
			name:            "main branch with explicit limit",
			branchName:      "main",
			checkpointCount: 20,
			isDefault:       true,
			limit:           5,
			wantContains:    []string{"Branch: main", "showing last 5 checkpoints", "Checkpoints: 20"},
			wantNotContains: []string{},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			output := formatBranchHeader(tt.branchName, tt.checkpointCount, tt.isDefault, tt.limit)

			for _, want := range tt.wantContains {
				if !strings.Contains(output, want) {
					t.Errorf("expected output to contain %q, got:\n%s", want, output)
				}
			}

			for _, notWant := range tt.wantNotContains {
				if strings.Contains(output, notWant) {
					t.Errorf("expected output to NOT contain %q, got:\n%s", notWant, output)
				}
			}
		})
	}
}

